#!/bin/sh
# Builds the password and ACL files from .env on a tmpfs, then starts mosquitto. Passwords go in
# on stdin so they never appear in a process list. Same approach as the camera relay's broker.
set -eu
umask 077
auth=/run/mosquitto-auth

# rf-analytics has its own login on the central server (password in a file generated by the RF
# stack's rf-bootstrap); other composes may leave it unset.
BROKER_RF_ANALYTICS_USER="${BROKER_RF_ANALYTICS_USER:-}"
BROKER_RF_ANALYTICS_PASSWORD="${BROKER_RF_ANALYTICS_PASSWORD:-}"
if [ -z "$BROKER_RF_ANALYTICS_PASSWORD" ] && [ -n "${BROKER_RF_ANALYTICS_PASSWORD_FILE:-}" ]; then
    BROKER_RF_ANALYTICS_PASSWORD="$(cat "$BROKER_RF_ANALYTICS_PASSWORD_FILE")"
fi
if [ -n "$BROKER_RF_ANALYTICS_USER" ] && [ -z "$BROKER_RF_ANALYTICS_PASSWORD" ]; then
    echo "BROKER_RF_ANALYTICS_USER is set without BROKER_RF_ANALYTICS_PASSWORD" >&2
    exit 1
fi

for user in "$BROKER_FUSION_USER" "$BROKER_PHYSICAL_USER" "$BROKER_RF_USER" \
    "$BROKER_CAMERA_USER" ${BROKER_RF_ANALYTICS_USER:+"$BROKER_RF_ANALYTICS_USER"}; do
    case "$user" in
    *:* | *\&* | *\|* | *\\* | *[[:space:]]*)
        echo "a broker user cannot hold a colon, &, |, backslash or space" >&2
        exit 1
        ;;
    esac
done

printf '%s\n%s\n' "$BROKER_FUSION_PASSWORD" "$BROKER_FUSION_PASSWORD" |
    mosquitto_passwd -c "$auth/passwd" "$BROKER_FUSION_USER" >/dev/null
printf '%s\n%s\n' "$BROKER_PHYSICAL_PASSWORD" "$BROKER_PHYSICAL_PASSWORD" |
    mosquitto_passwd "$auth/passwd" "$BROKER_PHYSICAL_USER" >/dev/null
printf '%s\n%s\n' "$BROKER_RF_PASSWORD" "$BROKER_RF_PASSWORD" |
    mosquitto_passwd "$auth/passwd" "$BROKER_RF_USER" >/dev/null
printf '%s\n%s\n' "$BROKER_CAMERA_PASSWORD" "$BROKER_CAMERA_PASSWORD" |
    mosquitto_passwd "$auth/passwd" "$BROKER_CAMERA_USER" >/dev/null
if [ -n "$BROKER_RF_ANALYTICS_USER" ]; then
    printf '%s\n%s\n' "$BROKER_RF_ANALYTICS_PASSWORD" "$BROKER_RF_ANALYTICS_PASSWORD" |
        mosquitto_passwd "$auth/passwd" "$BROKER_RF_ANALYTICS_USER" >/dev/null
    acl_src=/broker/aclfile
else # drop the rf-analytics block (its user line up to the next blank line)
    acl_src="$auth/aclfile.in"
    awk '/^user @RF_ANALYTICS_USER@/ { skip = 1 } skip && /^$/ { skip = 0 } !skip' /broker/aclfile >"$acl_src"
fi
sed -e "s|@FUSION_USER@|$BROKER_FUSION_USER|" \
    -e "s|@PHYSICAL_USER@|$BROKER_PHYSICAL_USER|" \
    -e "s|@RF_USER@|$BROKER_RF_USER|" \
    -e "s|@CAMERA_USER@|$BROKER_CAMERA_USER|" \
    -e "s|@RF_ANALYTICS_USER@|$BROKER_RF_ANALYTICS_USER|" \
    "$acl_src" >"$auth/aclfile"
rm -f "$auth/aclfile.in"
# Per-node logins, one per "node:password" entry, kept in .env by detection/central/node-logins.sh.
# The ACL lines of a login come from the function named in the call (it gets the node name).
rf_node_acl() { printf 'topic write detection/rf/nodes/%s/#\n' "$1"; }
camera_node_acl() {
    printf 'topic write detection/camera/#\n'
    printf 'topic read detection/rf/cues/camera\n'
}
# node_logins <env var name> <value> <login prefix> <ACL function>
node_logins() {
    name="$1" entries="$2" prefix="$3" acl="$4"
    for pair in $entries; do
        node="${pair%%:*}" pw="${pair#*:}"
        case "$node" in
        '' | -* | *[!a-z0-9-]*)
            echo "$name: bad node name '$node'" >&2
            exit 1
            ;;
        esac
        [ "$pw" != "$pair" ] && [ -n "$pw" ] || { echo "$name: $node has no password" >&2; exit 1; }
        printf '%s\n%s\n' "$pw" "$pw" | mosquitto_passwd "$auth/passwd" "$prefix$node" >/dev/null
        printf '\nuser %s%s\n' "$prefix" "$node" >>"$auth/aclfile"
        "$acl" "$node" >>"$auth/aclfile"
    done
    unset pair node pw name entries prefix acl
}
# RF nodes: login rf-node-<node>, BROKER_RF_NODE_LOGINS. Camera nodes: login cam-node-<node>,
# BROKER_CAMERA_NODE_LOGINS.
node_logins BROKER_RF_NODE_LOGINS "${BROKER_RF_NODE_LOGINS:-}" rf-node- rf_node_acl
node_logins BROKER_CAMERA_NODE_LOGINS "${BROKER_CAMERA_NODE_LOGINS:-}" cam-node- camera_node_acl
mkdir -p "$auth/conf.d"
# TLS listener on 8883 when a certificate is mounted (read-only) at /tls. Copied so that only the
# mosquitto user can read the key; the source can stay private to the store's owner.
if [ -r /tls/server.crt ] && [ -r /tls/server.key ]; then
    cp /tls/server.crt "$auth/tls.crt"
    cp /tls/server.key "$auth/tls.key"
    printf 'listener 8883\ncertfile %s\nkeyfile %s\ntls_version tlsv1.2\n' \
        "$auth/tls.crt" "$auth/tls.key" >"$auth/conf.d/tls.conf"
fi
chown -R mosquitto:mosquitto "$auth" /mosquitto/data
unset BROKER_FUSION_USER BROKER_FUSION_PASSWORD BROKER_PHYSICAL_USER BROKER_PHYSICAL_PASSWORD \
    BROKER_RF_USER BROKER_RF_PASSWORD BROKER_CAMERA_USER BROKER_CAMERA_PASSWORD \
    BROKER_RF_NODE_LOGINS BROKER_CAMERA_NODE_LOGINS \
    BROKER_RF_ANALYTICS_USER BROKER_RF_ANALYTICS_PASSWORD

exec mosquitto -c /broker/mosquitto.conf
